using System.Net;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;
using WireMock.RequestBuilders;
using WireMock.ResponseBuilders;
using WireMock.Server;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly WireMockServer provider = WireMockServer.Start();
    private readonly HttpClient client;
    private readonly HttpPaymentGateway sut;

    public HttpPaymentGatewayTests()
    {
        client = new HttpClient { BaseAddress = new Uri(provider.Url!) };
        sut = new HttpPaymentGateway(client);
    }

    [Fact]
    public async Task The_authorization_request_is_posted_with_reference_amount_and_currency()
    {
        Stub(200, """{"status":"approved"}""");

        await sut.AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);

        var received = Assert.Single(provider.LogEntries).RequestMessage;
        Assert.Equal("POST", received!.Method);
        Assert.Equal("/v1/authorizations", received.Path);
        Assert.StartsWith("application/json", received.Headers!["Content-Type"][0]);
        using var json = JsonDocument.Parse(received.Body!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        Stub(200, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        Stub(200, """{"status":"declined"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Unknown_extra_fields_in_the_answer_are_ignored()
    {
        Stub(200, """{"id":"auth_1","status":"approved","risk":{"score":3}}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_refusal_with_402_is_read_as_declined()
    {
        Stub(402, """{"error":"card_refused"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task An_unrecognised_status_is_never_read_as_approved()
    {
        Stub(200, """{"status":"pending"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task An_answer_without_a_status_is_never_read_as_approved()
    {
        Stub(200, """{"decision":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_error_statuses_surface_as_failures_not_as_a_decision(int status)
    {
        Stub(status, """{"error":"nope"}""");

        var failure = await Assert.ThrowsAsync<HttpRequestException>(Authorize);
        Assert.Equal((HttpStatusCode)status, failure.StatusCode);
    }

    [Fact]
    public async Task A_malformed_answer_surfaces_as_a_failure()
    {
        Stub(200, "<html>oops</html>");

        await Assert.ThrowsAsync<JsonException>(Authorize);
    }

    private Task<AuthorizationOutcome> Authorize() =>
        sut.AuthorizeAsync("ORD-7", new Money(12m, "EUR"), CancellationToken.None);

    private void Stub(int status, string body) =>
        provider.Given(Request.Create().WithPath("/v1/authorizations").UsingPost())
            .RespondWith(Response.Create().WithStatusCode(status)
                .WithHeader("Content-Type", "application/json").WithBody(body));

    public void Dispose()
    {
        client.Dispose();
        provider.Dispose();
    }
}
